import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";
import { RevealOnScroll } from "@/components/ui/RevealOnScroll";
import { Breadcrumbs } from "@/components/ui/Breadcrumbs";
import { sanityFetch } from "@/sanity/lib/live";
import { BLOG_POST_QUERY } from "@/sanity/lib/queries";
import { BlogContent } from "@/components/blog/BlogContent";
import { ArrowLeft, ArrowRight, Calendar, Clock, Share2 } from "lucide-react";
import Link from "next/link";
import { notFound } from "next/navigation";
import { format } from "date-fns";
import { Metadata } from "next";

export async function generateMetadata(props: { params: Promise<{ locale: string; slug: string }> }): Promise<Metadata> {
    const { locale, slug } = await props.params;
    const { data: post } = await sanityFetch({ query: BLOG_POST_QUERY, params: { slug, locale } });

    if (!post) return { title: "Post Not Found" };

    const baseUrl = "https://unionnationaltax.com";
    const path = `/blog/${slug}`;
    const canonicalUrl = locale === "en" ? `${baseUrl}${path}` : `${baseUrl}/${locale}${path}`;

    return {
        title: `${post.title} | Union National Tax`,
        description: post.excerpt,
        alternates: {
            canonical: canonicalUrl,
            languages: {
                en: `${baseUrl}${path}`,
                es: `${baseUrl}/es${path}`,
            },
        },
        openGraph: {
            images: [post.featuredImage?.asset?.url || ""],
        },
    };
}

export default async function BlogPostPage(props: { params: Promise<{ locale: string; slug: string }> }) {
    const params = await props.params;
    const { locale, slug } = params;
    const { data: post } = await sanityFetch({ query: BLOG_POST_QUERY, params: { slug, locale } });

    if (!post) {
        notFound();
    }

    const publishDate = post.publishedAt ? new Date(post.publishedAt) : new Date();

    return (
        <div className="min-h-dvh bg-white flex flex-col font-sans text-brand-900 antialiased selection:bg-gold-500 selection:text-white">
            <HeaderWrapper />

            <main id="main-content" className="flex-1">
                {/* Article Header */}
                <header className="relative pt-20 pb-16 md:pt-32 md:pb-24 bg-brand-900 overflow-hidden">
                    {/* Visual Decor */}
                    <div className="absolute inset-0 opacity-10 bg-[url('/images/pattern-grid.svg')] bg-repeat" />
                    <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-gold-500/10 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/3" />
                    
                    <div className="max-w-4xl mx-auto px-6 relative z-10">
                        <RevealOnScroll>
                            <Breadcrumbs 
                                items={[
                                    { label: "Journal", href: "/blog" },
                                    { label: post.title, href: `/blog/${post.slug}` }
                                ]} 
                            />
                            <Link 
                                href="/blog"
                                className="inline-flex items-center gap-2 text-gold-500 text-sm font-bold uppercase tracking-widest mb-10 hover:text-white transition-colors"
                            >
                                <ArrowLeft size={16} /> Back to Journal
                            </Link>

                            {post.categories && post.categories.length > 0 && (
                                <div className="flex gap-3 mb-8">
                                    {post.categories.map((cat: { title: string; slug: string }) => (
                                        <span key={cat.slug || cat.title} className="text-[10px] font-bold uppercase tracking-widest px-3 py-1 bg-gold-500/10 border border-gold-500/20 text-gold-500 rounded-full">
                                            {cat.title}
                                        </span>
                                    ))}
                                </div>
                            )}

                            <h1 className="text-4xl md:text-5xl lg:text-7xl font-bold text-white tracking-tighter mb-10 font-heading font-black leading-[1.05] drop-shadow-xl">
                                {post.title}
                            </h1>

                            <div className="flex flex-wrap items-center gap-8 text-slate-300 text-sm border-t border-white/10 pt-10">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-gold-500 flex items-center justify-center text-brand-900 font-bold font-heading shadow-lg shadow-gold-500/20">
                                        {post.author?.name?.charAt(0) || "U"}
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="text-white font-bold">{post.author?.name || "Union National Team"}</span>
                                        <span className="text-xs text-slate-400 font-medium">{post.author?.role || "Tax Strategist"}</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    <Calendar size={16} className="text-gold-500" />
                                    {format(publishDate, "MMMM dd, yyyy")}
                                </div>
                                <div className="flex items-center gap-2">
                                    <Clock size={16} className="text-gold-500" />
                                    {post.readingTime || 5} min read
                                </div>
                            </div>
                        </RevealOnScroll>
                    </div>
                </header>

                {/* Article Content */}
                <article className="py-20 px-6 bg-slate-50/30">
                    <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-16">
                        
                        {/* Main Content Side */}
                        <div className="lg:col-span-8">
                            <RevealOnScroll>
                                {post.featuredImage?.asset?.url && (
                                    <div className="mb-16 rounded-3xl overflow-hidden shadow-2xl relative group bg-white p-2">
                                        <img
                                            src={post.featuredImage.asset.url}
                                            alt={post.featuredImage.alt || post.title}
                                            className="w-full object-cover aspect-[16/9] rounded-2xl"
                                        />
                                    </div>
                                )}

                                <div className="bg-white rounded-[2.5rem] p-8 md:p-14 shadow-soft-green border border-slate-100">
                                    <BlogContent value={post.body} />

                                    {/* Social Share */}
                                    <div className="mt-20 py-8 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6">
                                        <h4 className="text-lg font-bold font-heading text-brand-900 px-4 py-2 bg-slate-50 rounded-lg">Share this strategy:</h4>
                                        <div className="flex gap-4">
                                            {['Twitter', 'LinkedIn', 'Facebook'].map(platform => (
                                                <button key={platform} className="w-12 h-12 rounded-full border border-slate-200 flex items-center justify-center hover:bg-brand-900 hover:border-brand-900 hover:text-white transition-all shadow-sm">
                                                    <Share2 size={18} />
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </RevealOnScroll>
                        </div>

                        {/* Sidebar */}
                        <aside className="lg:col-span-4 space-y-10">
                            <RevealOnScroll delay={200}>
                                <div className="bg-brand-900 rounded-[2rem] p-10 text-white relative overflow-hidden group shadow-2xl">
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-gold-500/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
                                    <h3 className="text-3xl font-bold font-heading mb-6 relative z-10 leading-tight">
                                        Maximize your <span className="text-gold-500">S-Corp strategy.</span>
                                    </h3>
                                    <p className="text-slate-300 mb-10 leading-relaxed font-sans relative z-10 text-lg font-light">
                                        Our partners save an average of $20K annually in self-employment taxes. See your potential savings in 60 seconds.
                                    </p>
                                    <Link 
                                        href="/s-corp-tax-advantage"
                                        className="inline-flex items-center justify-center w-full px-8 py-5 bg-gold-500 text-brand-900 font-extrabold rounded-xl hover:bg-white transition-all shadow-lg shadow-gold-500/20 relative z-10 font-heading text-lg group"
                                    >
                                        Run Savings Estimator <ArrowRight size={20} className="ml-2 group-hover:translate-x-2 transition-transform" />
                                    </Link>
                                </div>
                            </RevealOnScroll>

                            <RevealOnScroll delay={300}>
                                <div className="bg-white rounded-[2rem] p-10 border border-slate-200 shadow-soft">
                                    <h4 className="text-xl font-bold font-heading mb-6 text-brand-900">Expert Advisory</h4>
                                    <p className="text-slate-600 mb-8 leading-relaxed font-sans italic border-l-2 border-gold-500 pl-4">
                                        "Generalist accounting is the fastest way to overpay Uncle Sam. Specialized strategy is the only way to build real wealth."
                                    </p>
                                    <Link 
                                        href="/contact"
                                        className="flex items-center justify-between text-brand-900 font-extrabold border-b-2 border-brand-900/10 pb-4 hover:border-gold-500 group transition-all font-heading"
                                    >
                                        Book a Strategy Call
                                        <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform text-gold-500" />
                                    </Link>
                                </div>
                            </RevealOnScroll>
                        </aside>
                    </div>
                </article>
            </main>

            <Footer />
        </div>
    );
}

import { FAQPageSchema } from "@/components/seo/FAQPageSchema";
import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";
import { RevealOnScroll } from "@/components/ui/RevealOnScroll";
import { FAQList } from "@/components/faq/FAQList";
import { sanityFetch } from "@/sanity/lib/live";
import { FAQ_QUERY } from "@/sanity/lib/queries";
import { getLocale } from "next-intl/server";
import Link from "next/link";

export const revalidate = 3600; // Revalidate every hour

export const metadata = {
    title: "Frequently Asked Questions | Union National Tax",
    description: "Find answers to common questions about our tax services, pricing, and strategies for contractors and business owners.",
};

export default async function FAQPage(props: { params: Promise<{ locale: string }> }) {
    const params = await props.params;
    const locale = params.locale;
    
    // Fetch all FAQs with live data sync
    const { data: faqs } = await sanityFetch({ 
        query: FAQ_QUERY, 
        params: { locale } 
    });

    return (
        <main id="main-content" className="min-h-screen w-full bg-surface flex flex-col">
            <FAQPageSchema />
            <HeaderWrapper />

            <div className="flex-1 pt-32 pb-24">
                {/* Simple Hero */}
                <div className="max-w-7xl mx-auto px-6 mb-16 text-center">
                    <RevealOnScroll>
                        <span className="inline-block px-4 py-1.5 rounded-full bg-gold-50 text-gold-700 text-[10px] font-black uppercase tracking-[0.2em] mb-6 border border-gold-100">
                            Knowledge Base
                        </span>
                        <h1 className="text-4xl md:text-5xl lg:text-7xl font-bold text-brand-900 mb-8 font-heading tracking-tight">
                            The Strategy <span className="text-transparent bg-clip-text bg-gradient-to-r from-gold-400 to-gold-600 italic">Playbook</span>
                        </h1>
                        <p className="text-lg text-slate-500 max-w-2xl mx-auto leading-relaxed font-light">
                            Clear, technical answers to help you navigate the complexities of tax strategy, financial growth, and compliance.
                        </p>
                    </RevealOnScroll>
                </div>

                {/* Main FAQ Content with Filters */}
                <div className="max-w-7xl mx-auto px-6">
                    <FAQList items={faqs || []} />
                </div>

                {/* Contact CTA */}
                <div className="max-w-4xl mx-auto px-6 mt-32 text-center">
                    <RevealOnScroll delay={200} className="bg-brand-900 rounded-[2.5rem] p-12 md:p-20 relative overflow-hidden shadow-2xl shadow-brand-900/20">
                        {/* Background Design Elements */}
                        <div className="absolute top-0 right-0 w-1/2 h-full bg-gradient-to-l from-gold-500/10 to-transparent pointer-events-none" />
                        <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-gold-500/5 rounded-full blur-3xl pointer-events-none" />

                        <div className="relative z-10">
                            <h3 className="text-3xl md:text-4xl font-bold text-white mb-6 font-heading tracking-tight uppercase">
                                Still have <span className="text-gold-400">Questions?</span>
                            </h3>
                            <p className="text-slate-300 mb-10 max-w-xl mx-auto text-lg leading-relaxed font-light">
                                Every business is unique. Our team of Enrolled Agents and CPAs is ready to discuss your specific situation.
                            </p>
                            <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
                                <Link
                                    href="/contact"
                                    className="w-full sm:w-auto bg-gold-500 hover:bg-gold-600 text-brand-900 font-black py-5 px-10 rounded-2xl transition-all transform hover:scale-105 shadow-xl uppercase tracking-widest text-xs text-center"
                                >
                                    Book Free Strategy Call
                                </Link>
                                <Link
                                    href="mailto:support@unionnationaltax.com"
                                    className="w-full sm:w-auto bg-white/5 hover:bg-white/10 text-white border border-white/10 py-5 px-10 rounded-2xl transition-all font-bold text-xs uppercase tracking-widest text-center"
                                >
                                    Email Our Team
                                </Link>
                            </div>
                        </div>
                    </RevealOnScroll>
                </div>
            </div>

            <Footer />
        </main>
    );
}

import { HealthCheckSurvey } from "@/components/health-check/HealthCheckSurvey";
import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";

export const revalidate = 60; // Revalidate every minute

export const metadata = {
    title: "Business Financial Health Check | Union National Tax",
    description: "Get your Financial Health Score in 2 minutes. Discover if your business is thriving or needs attention with our free diagnostic tool.",
};

export default async function HealthCheckPage(props: { params: Promise<{ locale: string }> }) {
    const params = await props.params;
    const locale = params.locale;
    return (
        <main id="main-content" className="min-h-screen bg-slate-50 relative overflow-hidden">
            <HeaderWrapper />

            {/* Background Decorative Elements */}
            <div className="absolute top-0 left-0 w-full h-[500px] bg-gradient-to-b from-brand-500/5 to-transparent pointer-events-none" />
            <div className="absolute top-40 right-0 w-96 h-96 bg-gold-400/10 rounded-full blur-3xl pointer-events-none" />
            <div className="absolute bottom-0 left-20 w-64 h-64 bg-brand-500/5 rounded-full blur-3xl pointer-events-none" />

            <div className="container mx-auto px-4 pt-32 pb-20 relative z-10">
                <HealthCheckSurvey />
            </div>

            <Footer />
        </main>
    );
}

import { INDUSTRY_VERTICALS_QUERY } from "@/sanity/lib/queries";
import { sanityFetch } from "@/sanity/lib/live";
import { HubHero } from "@/components/hub/HubHero";
import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";
import { Metadata } from "next";

export const revalidate = 60;

export const metadata: Metadata = {
    title: "Industry Guides | Authority Hub",
    description: "Industry-specific tax strategies and playbooks for construction, real estate, e-commerce, and more.",
};

export default async function IndustriesPage(props: { params: Promise<{ locale: string }> }) {
    const { locale } = await props.params;

    const { data: industries } = await sanityFetch({
        query: INDUSTRY_VERTICALS_QUERY,
        params: { locale },
    });

    const featuredPlaybooks: any[] = [];

    return (
        <main id="main-content" className="bg-surface min-h-screen">
            <HeaderWrapper />
            <HubHero
                title="Industry Guides"
                subtitle="Tailored tax strategies and playbooks for your specific industry. Get the insights you need to maximize deductions and minimize liability."
                featuredPlaybooks={featuredPlaybooks}
                industryVerticals={industries || []}
            />
            <Footer />
        </main>
    );
}

import { PLAYBOOK_QUERY, PLAYBOOK_CHAPTER_QUERY } from "@/sanity/lib/queries";
import { sanityFetch } from "@/sanity/lib/live";
import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";
import { PlaybookNav } from "@/components/hub/PlaybookNav";
import { KeyTakeaways, ToolReferences } from "@/components/hub/ImpactCard";
import { GatedContentBox } from "@/components/hub/GatedContentBox";
import { RichText } from "@/components/blog/RichText";
import { notFound } from "next/navigation";
import { Metadata } from "next";
import Image from "next/image";
import { urlFor } from "@/sanity/lib/image";
import { Play, ArrowLeft } from "lucide-react";
import { extractString } from "@/lib/utils";
import Link from "next/link";
import { Playbook, PlaybookChapter } from "@/types/sanity";

export const revalidate = 60;

interface PageProps {
    params: Promise<{ locale: string; chapter: string }>;
}

export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { locale, chapter } = await props.params;
    const { data: chapterData } = await sanityFetch({
        query: PLAYBOOK_CHAPTER_QUERY,
        params: { slug: chapter, locale },
    });

    const typedChapter = chapterData as PlaybookChapter | null;

    if (!typedChapter) {
        return { title: "Chapter Not Found" };
    }

    return {
        title: `${extractString(typedChapter.title, locale)} | S-Corp Playbook`,
        description: `Chapter ${typedChapter.chapterNumber}: ${extractString(typedChapter.title, locale)}`,
    };
}

export default async function ChapterPage(props: PageProps) {
    const { locale, chapter: chapterSlug } = await props.params;

    const [{ data: playbook }, { data: chapter }] = await Promise.all([
        sanityFetch({ query: PLAYBOOK_QUERY, params: { slug: "s-corp-playbook", locale } }),
        sanityFetch({ query: PLAYBOOK_CHAPTER_QUERY, params: { slug: chapterSlug, locale } }),
    ]);

    const typedPlaybook = playbook as Playbook | null;
    const typedChapter = chapter as PlaybookChapter | null;

    if (!typedPlaybook || !typedChapter) {
        notFound();
    }

    const chapters = (typedPlaybook.chapters || []).map((c: any) => ({
        ...c,
        slug: typeof c.slug === 'string' ? c.slug : c.slug.current
    }));
    const currentIndex = chapters.findIndex((c: any) => c.slug === chapterSlug);
    const prevChapter = currentIndex > 0 ? chapters[currentIndex - 1] : null;
    const nextChapter = currentIndex < chapters.length - 1 ? chapters[currentIndex + 1] : null;

    return (
        <main id="main-content" className="bg-surface min-h-screen">
            <HeaderWrapper />

            <section className="relative overflow-hidden bg-forest-gradient pt-32 pb-8 text-white">
                <div className="absolute inset-0">
                    <div className="absolute -top-32 left-1/2 h-[520px] w-[900px] -translate-x-1/2 rounded-full bg-brand-500/20 blur-[140px]" />
                </div>

                <div className="relative z-10 mx-auto max-w-7xl px-6">
                    <Link
                        href="/hub/s-corp-playbook"
                        className="inline-flex items-center gap-2 text-sm text-white/60 hover:text-gold-200 transition-colors mb-8"
                    >
                        <ArrowLeft className="h-4 w-4" />
                        Back to Playbook
                    </Link>
                    <div className="flex items-center gap-4">
                        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-gold-500 text-lg font-bold text-brand-950">
                            {typedChapter.chapterNumber}
                        </span>
                        <h1 className="text-3xl font-semibold tracking-tight md:text-4xl lg:text-5xl font-heading">
                            {extractString(typedChapter.title, locale)}
                        </h1>
                    </div>
                </div>
            </section>

            <section className="mx-auto max-w-7xl px-6 py-12">
                <div className="grid gap-12 lg:grid-cols-[minmax(0,1fr)_340px]">
                    <div className="space-y-12">
                        {typedChapter.videoEmbed && (
                            <div className="relative aspect-video overflow-hidden rounded-2xl bg-brand-900">
                                <iframe
                                    src={typedChapter.videoEmbed}
                                    className="absolute inset-0 h-full w-full"
                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                    allowFullScreen
                                />
                            </div>
                        )}

                        {typedChapter.videoThumbnail && !typedChapter.videoEmbed && (
                            <div className="relative aspect-video overflow-hidden rounded-2xl bg-brand-900">
                                <Image
                                    src={urlFor(typedChapter.videoThumbnail).url()}
                                    alt={typedChapter.videoThumbnail.alt || extractString(typedChapter.title, locale)}
                                    fill
                                    className="object-cover"
                                />
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <div className="flex h-20 w-20 items-center justify-center rounded-full bg-gold-500/90 hover:bg-gold-400 transition-colors cursor-pointer">
                                        <Play className="h-8 w-8 text-brand-950 ml-1" />
                                    </div>
                                </div>
                            </div>
                        )}

                        {typedChapter.content && (
                            <div className="prose prose-invert max-w-none">
                                <RichText value={typedChapter.content} locale={locale} />
                            </div>
                        )}

                        {typedChapter.isGated && !typedChapter.gatedContent ? (
                            <GatedContentBox
                                title="Unlock Advanced Strategies"
                                description="This section contains advanced tactics. Enter your email to unlock this premium content."
                            />
                        ) : typedChapter.isGated && typedChapter.gatedContent ? (
                            <div>
                                <GatedContentBox
                                    title="Advanced Strategies Unlocked"
                                    description="Thanks for subscribing! Here are the advanced tactics for this chapter."
                                />
                                <div className="mt-8 prose prose-invert max-w-none">
                                    <RichText value={typedChapter.gatedContent} locale={locale} />
                                </div>
                            </div>
                        ) : null}

                        <KeyTakeaways takeaways={typedChapter.keyTakeaways?.map((t: string) => extractString(t, locale)) || []} />
                        <ToolReferences tools={typedChapter.tools?.map((t: string) => extractString(t, locale)) || []} />

                        <div className="flex items-center justify-between border-t border-white/10 pt-8">
                            {prevChapter ? (
                                <Link
                                    href={`/hub/s-corp-playbook/${prevChapter.slug}`}
                                    className="group flex items-center gap-2 text-sm text-white/60 hover:text-gold-200 transition-colors"
                                >
                                    <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                                    <span className="font-medium">Previous: {extractString(prevChapter.title, locale)}</span>
                                </Link>
                            ) : (
                                <div />
                            )}
                            {nextChapter && (
                                <Link
                                    href={`/hub/s-corp-playbook/${nextChapter.slug}`}
                                    className="group flex items-center gap-2 text-sm text-white/60 hover:text-gold-200 transition-colors"
                                >
                                    <span className="font-medium">Next: {extractString(nextChapter.title, locale)}</span>
                                    <ArrowLeft className="h-4 w-4 rotate-180 transition-transform group-hover:translate-x-1" />
                                </Link>
                            )}
                        </div>
                    </div>

                    <div className="hidden lg:block">
                        <div className="sticky top-24 space-y-6">
                            <PlaybookNav
                                playbookTitle={extractString(typedPlaybook.title, locale)}
                                chapters={chapters}
                                currentChapterSlug={chapterSlug}
                                locale={locale}
                            />
                        </div>
                    </div>
                </div>
            </section>

            <Footer />
        </main>
    );
}

import { PLAYBOOK_QUERY } from "@/sanity/lib/queries";
import { sanityFetch } from "@/sanity/lib/live";
import { HeaderWrapper } from "@/components/layout/HeaderWrapper";
import { Footer } from "@/components/layout/Footer";
import { PlaybookNav } from "@/components/hub/PlaybookNav";
import { GatedPdfButton } from "@/components/hub/GatedContentBox";
import Image from "next/image";
import { urlFor } from "@/sanity/lib/image";
import { notFound } from "next/navigation";
import { Metadata } from "next";
import { BookOpen, ArrowRight, Lock } from "lucide-react";
import { extractString } from "@/lib/utils";
import { Playbook, PlaybookChapter } from "@/types/sanity";
import Link from "next/link";

export const revalidate = 60;

interface PageProps {
    params: Promise<{ locale: string; slug?: string }>;
}

export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { locale } = await props.params;
    const { data: playbook } = await sanityFetch({
        query: PLAYBOOK_QUERY,
        params: { slug: "s-corp-playbook", locale },
    });

    const typedPlaybook = playbook as Playbook | null;

    if (!typedPlaybook) {
        return { title: "Playbook Not Found" };
    }

    return {
        title: `${extractString(typedPlaybook.title, locale)} | Authority Hub`,
        description: extractString(typedPlaybook.description, locale),
    };
}

export default async function PlaybookPage(props: PageProps) {
    const { locale } = await props.params;

    const [{ data: playbook }] = await Promise.all([
        sanityFetch({ query: PLAYBOOK_QUERY, params: { slug: "s-corp-playbook", locale } }),
    ]);

    const typedPlaybook = playbook as Playbook | null;

    if (!typedPlaybook) {
        notFound();
    }

    const chapters = (typedPlaybook.chapters || []).map((c: any) => ({
        ...c,
