import { useState } from 'react';
import Image from 'next/image';
import { Star, Quote, ChevronRight } from 'lucide-react';
import { TestimonialModal } from '@/components/ui/TestimonialModal';

interface TestimonialCardProps {
    testimonial: {
        _id: string;
        quote: string;
        clientName: string;
        clientTitle?: string;
        clientCompany?: string;
        rating: number;
        image?: {
            asset?: {
                url: string;
            };
        };
    };
    index: number;
    className?: string;
}

const truncateText = (
    text: string,
    maxLength: number = 200
): { truncated: string; isTruncated: boolean } => {
    if (text.length <= maxLength) {
        return { truncated: text, isTruncated: false };
    }

    // Find last space before maxLength to avoid cutting mid-word
    const lastSpace = text.lastIndexOf(' ', maxLength);
    const cutPoint = lastSpace > 0 ? lastSpace : maxLength;

    return {
        truncated: text.substring(0, cutPoint) + '...',
        isTruncated: true,
    };
};

export const TestimonialCard = ({ testimonial, index, className = "" }: TestimonialCardProps) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { truncated, isTruncated } = truncateText(testimonial.quote);

    const handleOpenModal = () => {
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
    };

    return (
        <>
            <div className={`h-full bg-brand-800/30 border border-brand-700/50 p-8 rounded-xl backdrop-blur-sm hover:border-gold-500/30 transition-all duration-300 group flex flex-col ${className}`}>
                {/* Stars */}
                <div className="flex gap-1 mb-6">
                    {[...Array(5)].map((_, i) => (
                        <Star
                            key={i}
                            className={`w-4 h-4 ${i < testimonial.rating
                                ? 'text-gold-500 fill-gold-500'
                                : 'text-brand-700'
                                }`}
                        />
                    ))}
                </div>

                {/* Quote */}
                <blockquote className="text-slate-300 leading-relaxed mb-4 flex-1 font-sans italic relative">
                    <Quote className="absolute -top-4 -left-2 w-8 h-8 text-gold-500/10 rotate-180" />
                    "{truncated}"
                </blockquote>

                {/* Read More Button */}
                {isTruncated && (
                    <button
                        type="button"
                        onClick={handleOpenModal}
                        className="inline-flex items-center gap-1 text-gold-500 hover:text-gold-400 transition-colors duration-200 text-sm font-medium mb-4 group/btn w-fit"
                    >
                        Read More
                        <ChevronRight className="w-4 h-4 group-hover/btn:translate-x-1 transition-transform duration-200" />
                    </button>
                )}

                {/* Author */}
                <div className="flex items-center gap-4 mt-auto pt-6 border-t border-brand-700/50">
                    {testimonial.image?.asset?.url ? (
                        <div className="relative w-12 h-12 rounded-full overflow-hidden border border-brand-600">
                            <Image
                                src={testimonial.image.asset.url}
                                alt={testimonial.clientName}
                                fill
                                className="object-cover"
                            />
                        </div>
                    ) : (
                        <div className="w-12 h-12 rounded-full bg-brand-700 flex items-center justify-center text-gold-500 font-bold border border-brand-600">
                            {testimonial.clientName.charAt(0)}
                        </div>
                    )}
                    <div>
                        <div className="font-bold text-white text-sm font-heading tracking-wide">
                            {testimonial.clientName}
                        </div>
                        <div className="text-xs text-brand-300 font-sans">
                            {testimonial.clientTitle}
                            {testimonial.clientTitle && testimonial.clientCompany && ', '}
                            {testimonial.clientCompany}
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal */}
            <TestimonialModal
                isOpen={isModalOpen}
                onClose={handleCloseModal}
                testimonial={testimonial}
            />
        </>
    );
};

'use client';

import React, { useCallback, useEffect, useState } from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import Autoplay from 'embla-carousel-autoplay';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { TestimonialCard } from './TestimonialCard';

interface TestimonialsCarouselProps {
    testimonials: any[];
}

export const TestimonialsCarousel = ({ testimonials }: TestimonialsCarouselProps) => {
    // Basic setup with loop enabled
    const [emblaRef, emblaApi] = useEmblaCarousel(
        { loop: true, align: 'start', slidesToScroll: 1 },
        [Autoplay({ delay: 5000, stopOnInteraction: false })]
    );

    const [selectedIndex, setSelectedIndex] = useState(0);
    const [scrollSnaps, setScrollSnaps] = useState<number[]>([]);

    const scrollPrev = useCallback(() => {
        if (emblaApi) emblaApi.scrollPrev();
    }, [emblaApi]);

    const scrollNext = useCallback(() => {
        if (emblaApi) emblaApi.scrollNext();
    }, [emblaApi]);

    const scrollTo = useCallback((index: number) => {
        if (emblaApi) emblaApi.scrollTo(index);
    }, [emblaApi]);

    const onSelect = useCallback(() => {
        if (!emblaApi) return;
        setSelectedIndex(emblaApi.selectedScrollSnap());
    }, [emblaApi]);

    useEffect(() => {
        if (!emblaApi) return;
        onSelect();
        setScrollSnaps(emblaApi.scrollSnapList());
        emblaApi.on('select', onSelect);
        emblaApi.on('reInit', onSelect);
    }, [emblaApi, onSelect]);

    return (
        <div className="relative">
            {/* Carousel Container */}
            <div className="overflow-hidden p-4 -m-4" ref={emblaRef}>
                <div className="flex touch-pan-y touch-pinch-zoom backface-visible">
                    {testimonials.map((testimonial, index) => (
                        <div
                            key={testimonial._id}
                            className="flex-[0_0_100%] min-w-0 md:flex-[0_0_50%] lg:flex-[0_0_33.333%] 2xl:flex-[0_0_25%] pl-4 md:pl-5 lg:pl-6"
                        >
                            <TestimonialCard
                                testimonial={testimonial}
                                index={index}
                                className="h-full"
                            />
                        </div>
                    ))}
                </div>
            </div>

            {/* Navigation Arrows - Desktop/Tablet (Outside) */}
            <button
                className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-4 md:-translate-x-8 lg:-translate-x-12 z-10 w-10 h-10 rounded-full bg-brand-800/80 backdrop-blur-sm border border-brand-700 flex items-center justify-center text-gold-500 shadow-lg hover:bg-brand-700 hover:scale-105 transition-all duration-300 group hidden md:flex"
                onClick={scrollPrev}
                aria-label="Previous slide"
            >
                <ChevronLeft className="w-6 h-6 group-hover:-translate-x-0.5 transition-transform" />
            </button>

            <button
                className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-4 md:translate-x-8 lg:translate-x-12 z-10 w-10 h-10 rounded-full bg-brand-800/80 backdrop-blur-sm border border-brand-700 flex items-center justify-center text-gold-500 shadow-lg hover:bg-brand-700 hover:scale-105 transition-all duration-300 group hidden md:flex"
                onClick={scrollNext}
                aria-label="Next slide"
            >
                <ChevronRight className="w-6 h-6 group-hover:translate-x-0.5 transition-transform" />
            </button>

            {/* Navigation Arrows - Mobile (Overlaid) */}
            <div className="flex md:hidden justify-between absolute top-1/2 -translate-y-1/2 left-4 right-4 z-10 pointer-events-none">
                <button
                    className="w-10 h-10 rounded-full bg-brand-800/80 backdrop-blur-sm border border-brand-700 flex items-center justify-center text-gold-500 shadow-lg pointer-events-auto active:scale-95 transition-transform"
                    onClick={scrollPrev}
                    aria-label="Previous slide"
                >
                    <ChevronLeft className="w-6 h-6" />
                </button>
                <button
                    className="w-10 h-10 rounded-full bg-brand-800/80 backdrop-blur-sm border border-brand-700 flex items-center justify-center text-gold-500 shadow-lg pointer-events-auto active:scale-95 transition-transform"
                    onClick={scrollNext}
                    aria-label="Next slide"
                >
                    <ChevronRight className="w-6 h-6" />
                </button>
            </div>

            {/* Pagination Dots */}
            <div className="flex justify-center flex-wrap gap-2 mt-10">
                {scrollSnaps.map((_, index) => (
                    <button
                        key={index}
                        className={`transition-all duration-300 rounded-full ${index === selectedIndex
                            ? 'w-3 h-3 bg-gold-500 shadow-[0_0_10px_rgba(212,175,55,0.5)]'
                            : 'w-2 h-2 bg-brand-700 hover:bg-brand-600'
                            }`}
                        onClick={() => scrollTo(index)}
                        aria-label={`Go to slide ${index + 1}`}
                    />
                ))}
            </div>
        </div>
    );
};

