"use client";

import { useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { cn } from "@/lib/utils";
import { ChartNoAxesCombined, ChevronDown, ChevronRight } from "lucide-react";
import { Link, usePathname } from "@/i18n/navigation";
import { getServiceHref, mergeServiceNavigationData, type ServiceSummary } from "./navigationData";

type ServicesDropdownProps = {
  services?: ServiceSummary[];
  isActive?: boolean;
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
};

export const ServicesDropdown = ({
  services,
  isActive: forcedIsActive,
  isOpen: controlledIsOpen,
  onOpenChange,
}: ServicesDropdownProps) => {
  const t = useTranslations("Header");
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const firstLinkRef = useRef<HTMLAnchorElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const openedByHoverRef = useRef(false);
  const shouldFocusFirstLinkRef = useRef(false);
  const pathname = usePathname();
  const isOpen = controlledIsOpen ?? internalIsOpen;
  const updateOpen = (nextIsOpen: boolean) => {
    if (controlledIsOpen === undefined) setInternalIsOpen(nextIsOpen);
    onOpenChange?.(nextIsOpen);
  };
  const menuId = "header-services-panel";
  const buttonId = "header-services-button";
  const isServicesActive = forcedIsActive ?? pathname.startsWith("/services");
  const serviceData = mergeServiceNavigationData(services);

  const visibleServices = serviceData.filter(
    (service) => !getServiceHref(service).startsWith("/industries/"),
  );

  const groupDefinitions = [
    {
      id: "advisory",
      title: t("servicesGroupAdvisory"),
      hrefs: ["/s-corp-tax-advantage", "/tax-planning", "/strategic-bookkeeping", "/fractional-cfo"],
    },
    {
      id: "implementation",
      title: t("servicesGroupImplementation"),
      hrefs: ["/tax-preparation-and-filing", "/new-business-formation", "/payroll-services"],
    },
  ];

  const recognizedHrefs = new Set(groupDefinitions.flatMap((group) => group.hrefs));
  const serviceByHref = new Map(visibleServices.map((service) => [getServiceHref(service), service]));
  const serviceGroups = groupDefinitions
    .map((group) => ({
      ...group,
      services: group.hrefs
        .map((href) => serviceByHref.get(href))
        .filter((service): service is ServiceSummary => Boolean(service)),
    }))
    .filter((group) => group.services.length > 0);
  const otherServices = visibleServices.filter(
    (service) => !recognizedHrefs.has(getServiceHref(service)),
  );

  if (otherServices.length > 0) {
    serviceGroups.push({
      id: "other",
      title: t("servicesGroupOther"),
      hrefs: otherServices.map(getServiceHref),
      services: otherServices,
    });
  }

  const firstService = serviceGroups.flatMap((group) => group.services)[0];
  const firstServiceKey = firstService?._id || firstService?.slug?.current || firstService?.title;

  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelHoverCloseTimer = () => {
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current);
      hoverTimeoutRef.current = null;
    }
  };

  useEffect(() => {
    return () => cancelHoverCloseTimer();
  }, []);

  useEffect(() => {
    if (!isOpen) return;

    const handlePointerDown = (event: MouseEvent | TouchEvent) => {
      const target = event.target as Node | null;
      if (target && !containerRef.current?.contains(target)) {
        cancelHoverCloseTimer();
        updateOpen(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);
    document.addEventListener("touchstart", handlePointerDown);
    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
      document.removeEventListener("touchstart", handlePointerDown);
    };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || !shouldFocusFirstLinkRef.current) return;

    shouldFocusFirstLinkRef.current = false;
    firstLinkRef.current?.focus();
  }, [isOpen]);

  useEffect(() => {
    cancelHoverCloseTimer();
    openedByHoverRef.current = false;
    updateOpen(false);
  }, [pathname]);

  const handleClose = () => {
    cancelHoverCloseTimer();
    openedByHoverRef.current = false;
    shouldFocusFirstLinkRef.current = false;
    updateOpen(false);
  };

  const handlePointerEnter = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;

    cancelHoverCloseTimer();
    openedByHoverRef.current = true;
    updateOpen(true);
  };

  const handlePointerLeave = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;

    cancelHoverCloseTimer();
    hoverTimeoutRef.current = setTimeout(() => {
      handleClose();
    }, 200);
  };

  const handleTriggerClick = () => {
    cancelHoverCloseTimer();
    // A mouse entering the trigger opens the panel before its click fires. Keep
    // that first click open; subsequent clicks still toggle as users expect.
    if (openedByHoverRef.current) {
      openedByHoverRef.current = false;
      updateOpen(true);
      return;
    }

    updateOpen(!isOpen);
  };

  const handleButtonKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "ArrowDown" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      cancelHoverCloseTimer();
      shouldFocusFirstLinkRef.current = true;
      updateOpen(true);
    }

    if (event.key === "Escape") {
      event.preventDefault();
      handleClose();
    }
  };

  const handleContainerBlur = (event: React.FocusEvent<HTMLDivElement>) => {
    const nextTarget = event.relatedTarget as Node | null;
    if (!nextTarget || !containerRef.current?.contains(nextTarget)) handleClose();
  };

  const handlePanelKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      handleClose();
      buttonRef.current?.focus();
    }
  };

  const getServiceLabel = (href: string, fallbackTitle?: string) => {
    switch (href) {
      case "/tax-planning": return t("serviceLabels.taxPlanning");
      case "/s-corp-tax-advantage": return t("serviceLabels.sCorp");
      case "/strategic-bookkeeping": return t("serviceLabels.bookkeeping");
      case "/fractional-cfo": return t("serviceLabels.fractionalCfo");
      case "/new-business-formation": return t("serviceLabels.formation");
      case "/payroll-services": return t("serviceLabels.payroll");
      case "/tax-preparation-and-filing": return t("serviceLabels.taxPreparation");
      default: return fallbackTitle || t("servicesDropdownFallbackServiceTitle");
    }
  };

  const renderServiceLink = (service: ServiceSummary) => {
    const href = getServiceHref(service);
    const serviceTitle = getServiceLabel(href, service.title);
    const serviceKey = service._id || service.slug?.current || serviceTitle;
    const isCurrent = pathname === href || pathname.startsWith(`${href}/`);
    return (
      <li key={serviceKey}>
        <Link
          ref={serviceKey === firstServiceKey ? firstLinkRef : undefined}
          href={href}
          onClick={handleClose}
          aria-current={isCurrent ? "page" : undefined}
          className={cn(
            "group/item flex min-h-10 items-center justify-between gap-4 rounded-md px-2 py-1 text-base transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold-300",
            isCurrent
              ? "bg-gold-500/15 text-gold-300"
              : "text-white hover:bg-white/5 hover:text-gold-200",
          )}
        >
          <span>{serviceTitle}</span>
          <ChevronRight className="h-4 w-4 shrink-0 text-gold-300 transition-transform group-hover/item:translate-x-0.5 motion-reduce:transition-none" aria-hidden="true" />
        </Link>
      </li>
    );
  };

  return (
    <div
      ref={containerRef}
      className="relative"
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onBlurCapture={handleContainerBlur}
    >
      <button
        ref={buttonRef}
        type="button"
        id={buttonId}
        className={cn(
          "strategy-services-trigger group relative flex items-center gap-1.5 rounded-md px-3 py-2 text-sm font-medium transition-colors duration-200",
          isServicesActive || isOpen
            ? "bg-white/10 text-white"
            : "text-white hover:bg-white/5",
          "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold-300",
        )}
        onClick={handleTriggerClick}
        onKeyDown={handleButtonKeyDown}
        aria-expanded={isOpen}
        aria-haspopup="true"
        aria-controls={menuId}
      >
        <span className="relative z-10">{t("services")}</span>
        <ChevronDown
          size={15}
          aria-hidden="true"
          className={cn("relative z-10 transition-transform duration-200", isOpen && "rotate-180")}
        />
      </button>

      {isOpen ? (
        <div
          id={menuId}
          role="region"
          aria-labelledby={buttonId}
          onPointerEnter={handlePointerEnter}
          onPointerLeave={handlePointerLeave}
          onKeyDown={handlePanelKeyDown}
          className="fixed left-[calc(50%+6rem)] z-30 w-[min(59rem,calc(100vw-3rem))] -translate-x-1/2 overflow-y-auto overscroll-contain pt-2 before:absolute before:-top-4 before:left-0 before:right-0 before:h-4 before:content-['']"
          style={{
            top: "calc(var(--header-height, 76px) - 0.5rem)",
            maxHeight: "calc(100dvh - var(--header-height, 76px) - 1rem)",
          }}
        >
          <div className="overflow-hidden rounded-2xl border border-gold-600/60 bg-brand-500 shadow-2xl shadow-black/60">
            <div className="grid grid-cols-[1fr_1fr_0.9fr] px-7 py-6">
                {serviceGroups.slice(0, 2).map((group, index) => (
                  <section
                    key={group.id}
                    aria-labelledby={`${menuId}-${group.id}`}
                    className={cn("border-r border-white/20", index === 0 ? "pr-7" : "px-7")}
                  >
                    <h3
                      id={`${menuId}-${group.id}`}
                      className="text-xs font-semibold uppercase tracking-[0.18em] text-gold-300"
                    >
                      {group.title}
                    </h3>
                    <ul className="mt-3 space-y-0.5">
                      {group.services.map(renderServiceLink)}
                    </ul>
                  </section>
                ))}
                <div className="flex flex-col justify-center gap-3 pl-7">
                  <Link
                    href="/services#services"
                    onClick={handleClose}
                    className="group flex min-h-12 items-center justify-between gap-3 rounded-lg border border-gold-300 px-4 text-sm font-medium text-gold-200 transition-colors hover:bg-gold-500/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold-300"
                  >
                    <ChartNoAxesCombined className="h-4 w-4" aria-hidden="true" />
                    <span className="mr-auto">{t("servicesDropdownCompare")}</span>
                    <ChevronRight className="h-4 w-4" aria-hidden="true" />
                  </Link>
                  <Link
                    href="/services"
                    onClick={handleClose}
                    aria-current={pathname === "/services" ? "page" : undefined}
                    className="group flex min-h-12 items-center justify-between gap-3 rounded-lg bg-gold-300 px-4 text-sm font-semibold text-brand-950 transition-colors hover:bg-gold-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold-300"
                  >
                    {t("servicesDropdownViewAll")}
                    <ChevronRight className="h-4 w-4" aria-hidden="true" />
                  </Link>
                </div>
              </div>
              {serviceGroups.slice(2).map((group) => (
                <section key={group.id} aria-labelledby={`${menuId}-${group.id}`} className="border-t border-white/15 px-7 py-4">
                  <h3 id={`${menuId}-${group.id}`} className="text-xs font-semibold uppercase tracking-[0.18em] text-gold-300">{group.title}</h3>
                  <ul className="mt-2 grid grid-cols-2 gap-x-8">{group.services.map(renderServiceLink)}</ul>
                </section>
              ))}
          </div>
        </div>
      ) : null}
    </div>
  );
};

"use client";
import { SanityBlock } from "@/types/sanity";

import { PortableText } from "next-sanity";
import { Link as ScrollLink } from "react-scroll";
import { m, LazyMotion, domMax } from "framer-motion";
import { Info, ChevronRight, Menu, X } from "lucide-react";
import { useState, useEffect } from "react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

interface Heading {
    id: string;
    text: string;
    level: number;
}

interface LegalContentClientProps {
    body: SanityBlock[];
    title: string;
}

export function LegalContentClient({ body, title }: LegalContentClientProps) {
    const [activeId, setActiveId] = useState<string>("");
    const [isMobileTocOpen, setIsMobileTocOpen] = useState(false);

    // Extract headings for TOC
    const headings: Heading[] = (body || [])
        .filter((block) => block._type === "block" && /^h[1-4]$/.test(block.style || ""))
        .map((block) => {
            const text = block.children?.map((c) => c.text).join("") || "";
            const id = text.toLowerCase().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-");
            return {
                id,
                text,
                level: parseInt((block.style || "h2").replace("h", ""), 10),
            };
        });

    // Custom components for PortableText to include IDs and "Plain Language" callouts
    const components = {
        block: {
            h2: ({ children, value }: any) => {
                const id = value.children?.map((c: any) => c.text).join("").toLowerCase().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-");
                return (
                    <h2 id={id} className="text-2xl font-bold text-brand-900 mt-12 mb-6 scroll-mt-24 font-heading">
                        {children}
                    </h2>
                );
            },
            h3: ({ children, value }: any) => {
                const id = value.children?.map((c: any) => c.text).join("").toLowerCase().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-");
                return (
                    <h3 id={id} className="text-xl font-bold text-brand-900 mt-8 mb-4 scroll-mt-24 font-heading">
                        {children}
                    </h3>
                );
            },
            normal: ({ children }: any) => {
                // Simple logic for "Plain Language" callouts: if text starts with "Plain Language:"
                const text = Array.isArray(children) ? children[0] : children;
                if (typeof text === 'string' && text.startsWith('Plain Language:')) {
                    return (
                        <div className="my-8 p-4 bg-gold-50/50 border-l-4 border-gold-500 rounded-r-lg flex gap-4">
                            <Info className="w-5 h-5 text-gold-600 shrink-0 mt-0.5" />
                            <div>
                                <span className="block text-[10px] font-bold uppercase tracking-wider text-gold-700 mb-1">In Plain English</span>
                                <p className="text-sm text-gold-900/80 leading-relaxed italic">{text.replace('Plain Language:', '').trim()}</p>
                            </div>
                        </div>
                    );
                }
                return <p className="mb-4 leading-relaxed text-brand-900/80">{children}</p>;
            }
        },
        list: {
            bullet: ({ children }: any) => <ul className="list-disc pl-6 mb-6 space-y-2 text-brand-900/80">{children}</ul>,
            number: ({ children }: any) => <ol className="list-decimal pl-6 mb-6 space-y-2 text-brand-900/80">{children}</ol>,
        },
    };

    return (
        <LazyMotion features={domMax}>
            <div className="relative grid grid-cols-1 lg:grid-cols-[1fr_250px] gap-12 items-start">
                {/* Main Content */}
                <div className="prose prose-slate max-w-none prose-headings:font-heading prose-p:font-sans">
                    <PortableText value={body} components={components} />
                </div>

                {/* Desktop Sidebar TOC */}
                <aside className="hidden lg:block sticky top-32 self-start border-l border-slate-200 pl-6 py-2">
                    <h4 className="text-[10px] uppercase tracking-[0.2em] font-bold text-slate-400 mb-6">Contents</h4>
                    <nav className="space-y-4">
                        {headings.map((heading) => (
                            <ScrollLink
                                key={heading.id}
                                to={heading.id}
                                spy={true}
                                smooth={true}
                                offset={-100}
                                duration={500}
                                onSetActive={() => setActiveId(heading.id)}
                                className={cn(
                                    "block text-sm cursor-pointer transition-all duration-300",
                                    heading.level > 2 ? "pl-4 text-xs" : "",
                                    activeId === heading.id
                                        ? "text-gold-600 font-semibold translate-x-1"
                                        : "text-slate-500 hover:text-brand-900"
                                )}
                            >
                                {heading.text}
                            </ScrollLink>
                        ))}
                    </nav>
                </aside>

                {/* Mobile Floating TOC Trigger */}
                <button
                    onClick={() => setIsMobileTocOpen(!isMobileTocOpen)}
                    className="lg:hidden fixed bottom-8 right-8 z-50 w-12 h-12 bg-brand-900 text-white rounded-full shadow-2xl flex items-center justify-center border border-white/10 active:scale-95 transition-transform"
                >
                    {isMobileTocOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
                </button>

                {/* Mobile TOC Overlay */}
                {isMobileTocOpen && (
                    <m.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="lg:hidden fixed inset-x-4 bottom-24 z-50 bg-white rounded-2xl shadow-2xl border border-slate-100 p-6 max-h-[60vh] overflow-y-auto"
                    >
                        <h4 className="text-xs uppercase tracking-widest font-bold text-slate-400 mb-6">Jump to section</h4>
                        <div className="grid gap-4">
                            {headings.map((heading) => (
                                <ScrollLink
                                    key={heading.id}
                                    to={heading.id}
                                    smooth={true}
                                    offset={-80}
                                    onClick={() => setIsMobileTocOpen(false)}
                                    className="flex items-center justify-between text-brand-900 font-medium py-2 border-b border-slate-50"
                                >
                                    <span>{heading.text}</span>
                                    <ChevronRight className="w-4 h-4 text-slate-400" />
                                </ScrollLink>
                            ))}
                        </div>
                    </m.div>
                )}
            </div>
        </LazyMotion>
    );
}

import { Check, X, Info } from "lucide-react";
import * as Icons from "lucide-react";
import { cn } from "@/lib/utils";

// Define strict types matching the Sanity query
interface PricingTier {
    _id: string;
    name: string;
    slug: { current: string };
    category: string;
    price?: string;
    billingPeriod?: string;
    tagline?: string; // Used sometimes as a subheader
    bestFor?: string; // Column: Best For
    includes?: string; // Column: Includes
    ctaText?: string;
    ctaUrl?: string;
    displayOrder?: number;
}

interface TaxPrepGridProps {
    tiers: PricingTier[];
}

export function TaxPrepGrid({ tiers }: TaxPrepGridProps) {
    if (!tiers || tiers.length === 0) return null;

    // Filter for Individual and Business tiers
    const individualTiers = tiers.filter(t => t.category === "individual");
    const businessTiers = tiers.filter(t => t.category === "business");

    // Helper to render a section
    const renderSection = (title: string, items: PricingTier[]) => {
        if (items.length === 0) return null;

        return (
            <div className="mb-12 last:mb-0">
                <h3 className="text-xl font-bold text-brand-900 font-heading mb-6 pl-4 border-l-4 border-gold-500">{title}</h3>

                <div className="overflow-hidden rounded-xl border border-brand-900/10 shadow-sm bg-white">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-brand-50/50 border-b border-brand-900/5">
                                    <th className="py-4 px-6 text-xs font-bold text-brand-900 uppercase tracking-widest w-[25%]">Service Level</th>
                                    <th className="py-4 px-6 text-xs font-bold text-brand-900/60 uppercase tracking-widest w-[30%]">Best For</th>
                                    <th className="py-4 px-6 text-xs font-bold text-brand-900/60 uppercase tracking-widest w-[30%]">Includes</th>
                                    <th className="py-4 px-6 text-xs font-bold text-brand-900/60 uppercase tracking-widest text-right w-[15%]">Pricing</th>
                                </tr>
                            </thead>
                            <tbody>
                                {items.map((item, idx) => (
                                    <tr
                                        key={item._id}
                                        className={cn(
                                            "group transition-colors hover:bg-brand-50/30",
                                            idx !== items.length - 1 ? "border-b border-brand-900/5" : ""
                                        )}
                                    >
                                        <td className="py-5 px-6">
                                            <span className="font-bold text-brand-900 text-lg block">{item.name}</span>
                                            {item.tagline && (
                                                <span className="text-xs text-brand-900/50 mt-1 block font-medium">{item.tagline}</span>
                                            )}
                                        </td>
                                        <td className="py-5 px-6 text-sm text-brand-900/80 leading-relaxed max-w-xs">
                                            {item.bestFor}
                                        </td>
                                        <td className="py-5 px-6 text-sm text-brand-900/70 leading-relaxed max-w-xs font-medium">
                                            {item.includes}
                                        </td>
                                        <td className="py-5 px-6 text-right">
                                            <div className="flex flex-col items-end">
                                                <span className="text-xl font-bold text-brand-900 font-data tabular-nums">{item.price}</span>
                                                {item.billingPeriod === 'one-time' ? null : (
                                                    <span className="text-[10px] text-brand-900/40 uppercase tracking-wider font-bold">
                                                        /{item.billingPeriod || 'return'}
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="max-w-7xl mx-auto px-6 mt-24">
            <div className="text-center mb-12">
                <h2 className="text-3xl font-bold text-brand-900 font-heading mb-3">Compliance & Tax Preparation</h2>
                <p className="text-brand-900/60 max-w-2xl mx-auto">
                    Professional, audit-proof filing services for individuals and businesses who need their returns done right, without the full advisory retainer.
                </p>
            </div>

            {renderSection("Individual Tax Services", individualTiers)}
            {renderSection("Business Tax Services", businessTiers)}

            {/* Included With Every Return Section */}
            <div className="mt-20 pt-16 border-t border-brand-900/10">
                <h3 className="text-sm font-bold text-gold-600 uppercase tracking-[0.2em] text-center mb-10">
                    What&apos;s Included With Every Return
                </h3>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-8 md:gap-4">
                    {[
                        { icon: Icons.ShieldCheck, text: "3-Year Audit Protection" },
                        { icon: Icons.FileCheck, text: "EA-Prepared Return" },
                        { icon: Icons.Lock, text: "Secure Client Portal" },
                        { icon: Icons.BarChart3, text: "Accuracy & Compliance Review" },
                        { icon: Icons.Phone, text: "Post-Filing Support" },
                    ].map((item, i) => (
                        <div key={i} className="flex flex-col items-center text-center group">
                            <div className="w-12 h-12 rounded-xl bg-brand-50 flex items-center justify-center text-brand-900 mb-4 transition-all duration-300 group-hover:bg-brand-900 group-hover:text-gold-400 group-hover:scale-110">
                                <item.icon className="w-6 h-6" />
                            </div>
                            <span className="text-xs md:text-sm font-bold text-brand-900/70 leading-tight px-2 group-hover:text-brand-900 transition-colors">
                                {item.text}
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Link } from "@/i18n/navigation";
import Image from "next/image";
import { useLocale } from "next-intl";
import { BookOpen, FileText, Calculator, ChevronDown, X, ChevronRight, Download, Activity, UtensilsCrossed } from "lucide-react";
import { extractString } from "@/lib/utils";
import { InteractiveToolsList } from "./InteractiveToolsList";
import { ConstructionTaxChecklist } from "./lead-magnets/ConstructionTaxChecklist";
import { SCorpSavingsCalculator } from "./lead-magnets/SCorpSavingsCalculator";
import { SCorpElectionChecklist } from "./lead-magnets/SCorpElectionChecklist";

import { TaxHealthScore } from "./lead-magnets/TaxHealthScore";
import { RestaurantProfitLeakAssessment } from "@/components/intake/RestaurantProfitLeakAssessment";

interface Category {
    _id: string;
    title: string;
    slug: string;
}

interface ResourceItem {
    _type: "playbook" | "blogPost";
    _id: string;
    title: string;
    slug: string;
    description?: string;
    excerpt?: string;
    coverImage?: {
        asset: {
            url: string;
        };
        alt?: string;
    };
    featuredImage?: {
        asset: {
            url: string;
        };
        alt?: string;
    };
    publishedAt?: string;
    readingTime?: number;
    chapterCount?: number;
    categories?: Category[];
}

interface ResourceGridProps {
    playbooks: ResourceItem[];
    blogPosts: ResourceItem[];
    categories: Category[];
    showLeadMagnets: boolean;
    showBlogPosts: boolean;
    showTools: boolean;
}

type FilterType = "leadMagnets" | "blogPosts" | "tools";

export function ResourceGrid({
    playbooks,
    blogPosts,
    categories,
    showLeadMagnets,
    showBlogPosts,
    showTools
}: ResourceGridProps) {
    const locale = useLocale();
    const [activeFilter, setActiveFilter] = useState<FilterType>("blogPosts");
    const [activeCategory, setActiveCategory] = useState<Category | null>(null);
    const [viewingLeadMagnet, setViewingLeadMagnet] = useState<string | null>(null);

    const filters: { key: FilterType; label: string; icon?: React.ReactNode }[] = [];

    if (showBlogPosts) {
        filters.push({ key: "blogPosts", label: "Blog Posts", icon: <FileText className="w-4 h-4" /> });
    }
    if (showLeadMagnets) {
        filters.push({ key: "leadMagnets", label: "Lead Magnets", icon: <BookOpen className="w-4 h-4" /> });
    }
    if (showTools) {
        filters.push({ key: "tools", label: "Interactive Tools", icon: <Calculator className="w-4 h-4" /> });
    }

    const allResources: ResourceItem[] = [];

    if (showLeadMagnets) {
        playbooks.forEach(p => allResources.push({ ...p, _type: "playbook" }));
    }
    if (showBlogPosts) {
        blogPosts.forEach(p => allResources.push({ ...p, _type: "blogPost" }));
    }

    const filteredResources = allResources.filter(resource => {
        const typeMatch =
            (activeFilter === "leadMagnets" && resource._type === "playbook") ||
            (activeFilter === "blogPosts" && resource._type === "blogPost");

        const categoryMatch = !activeCategory ||
            resource.categories?.some(cat => cat.slug === activeCategory.slug);

        return typeMatch && categoryMatch;
    });

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString("en-US", {
            month: "short",
            day: "numeric",
            year: "numeric",
        });
    };

    return (
        <section className="bg-white py-16 lg:py-24">
            <div className="w-full px-4 sm:px-6">
                {!viewingLeadMagnet && (
                    <div className="flex flex-col lg:flex-row gap-6 items-center justify-between mb-12">
                        {/* Segmented Control Filter */}
                        <div className="bg-slate-100/80 backdrop-blur-md p-1.5 rounded-full inline-flex items-center gap-1 border border-slate-200/60 shadow-[inset_0_1px_2px_rgba(0,0,0,0.02)]">
                            {filters.map(filter => (
                                <button
                                    key={filter.key}
                                    onClick={() => {
                                        setActiveFilter(filter.key);
                                        setActiveCategory(null);
                                    }}
                                    className={`relative flex items-center gap-2 px-6 py-2 rounded-full text-sm font-semibold transition-all duration-300 z-10 ${activeFilter === filter.key
                                        ? "text-brand-900"
                                        : "text-slate-500 hover:text-slate-900"
                                        }`}
                                >
                                    {activeFilter === filter.key && (
                                        <div className="absolute inset-0 bg-white rounded-full shadow-sm ring-1 ring-slate-900/5 -z-10 animate-in fade-in zoom-in-95 duration-200" />
                                    )}
