                {viewingLeadMagnet ? (
                    <div>
                        <div className="mb-8">
                            <button
                                onClick={() => setViewingLeadMagnet(null)}
                                className="inline-flex items-center gap-2 text-slate-500 hover:text-brand-900 transition-colors font-medium"
