  { topic: "profit", icon: BarChart3 },
  { topic: "finance", icon: UsersRound },
  { topic: "retirement", icon: Leaf },
];

const formatPrice = (price: number) =>
  `$${new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(price)}`;

const productTopics = (product: ShopDesktopProduct): Topic[] => {
  const text =
    `${product.title} ${product.slug} ${product.category || ""}`.toLowerCase();
  const matches: Topic[] = [];
  if (/construction|contractor/.test(text)) matches.push("construction");
  if (/retirement/.test(text)) matches.push("retirement");
  if (/tax|s-corp|real estate/.test(text)) matches.push("tax");
  if (/s-corp/.test(text)) matches.push("scorp");
  if (/profit|growth|3m|freedom|restaurant/.test(text)) matches.push("profit");
  if (/cfo|financial|freedom|money/.test(text)) matches.push("finance");
  if (/template/.test(text) || product.format.toLowerCase() === "template")
    matches.push("templates");
  if (/video|course/.test(text) || product.format.toLowerCase() === "course")
    matches.push("courses");
  return matches;
};

function ResourceAction({
  product,
  label,
  className,
  detailLabel,
}: {
  product: ShopDesktopProduct;
  label: string;
  className: string;
  detailLabel?: string;
}) {
  const addItem = useCartStore((state) => state.addItem);
  const toggleCart = useCartStore((state) => state.toggleCart);
  const editions =
    product.editions?.map((edition) =>
      normalizeProductEdition(product._id, edition),
    ) || [];
  const defaultEdition = editions.length === 1 ? editions[0] : null;
  const hasCheckout = Boolean(
    defaultEdition?.stripePriceId || product.stripePriceId || product.buyLink,
  );

  if (editions.length > 1 || !hasCheckout) {
    return (
      <Link href={`/shop/${product.slug}`} className={className}>
        {editions.length > 1 ? label : detailLabel || label}
        <ArrowRight className="h-4 w-4" aria-hidden="true" />
      </Link>
    );
  }

  const addToCart = () => {
    addItem({
      id: buildCartItemKey(product._id, defaultEdition?.id),
      productId: product._id,
      editionId: defaultEdition?.id,
      editionName: defaultEdition?.name,
      slug: product.slug,
      title: defaultEdition
        ? `${product.title} - ${defaultEdition.name}`
        : product.title,
      image: product.imageUrl || "/images/og-default.png",
      format: defaultEdition?.format || product.format,
      fulfillmentType: defaultEdition?.fulfillmentType,
      requiresShipping: defaultEdition?.requiresShipping,
      price: defaultEdition?.price ?? product.price,
      buyLink: product.buyLink,
      stripeProductId: product.stripeProductId,
      stripePriceId: defaultEdition?.stripePriceId || product.stripePriceId,
    });
    toggleCart();
  };

  return (
    <button type="button" onClick={addToCart} className={className}>
      {label}
      <ShoppingCart className="h-4 w-4" aria-hidden="true" />
    </button>
  );
}

