"use client";

import { motion } from "framer-motion";
import { Star } from "lucide-react";
import Image from "next/image";
import { useSyncExternalStore } from "react";

const noopSubscribe = () => () => {};

function useHydrated(): boolean {
    return useSyncExternalStore(noopSubscribe, () => true, () => false);
}

interface Testimonial {
    _id: string;
    clientName: string;
    clientTitle: string;
    clientCompany: string;
    quote: string;
    rating: number;
    imageUrl?: string;
}

interface TestimonialWallProps {
    testimonials?: Testimonial[];
    backgroundImage?: {
        url?: string;
        alt?: string;
    };
}

export function TestimonialWall({ testimonials: propTestimonials, backgroundImage }: TestimonialWallProps) {
    const hydrated = useHydrated();

    const displayTestimonials = propTestimonials?.filter((testimonial) => testimonial.quote && testimonial.clientName) || [];

    if (displayTestimonials.length === 0) {
        return null;
    }

    const featured = displayTestimonials[0];
    const backgroundImageUrl = backgroundImage?.url || "/images/testimonial-cinematic-bg.png";
    const backgroundImageAlt = backgroundImage?.alt || "Union National Tax product testimonial background";
    return (
        <section id="reviews" className="scroll-mt-24 relative py-16 lg:py-20 overflow-hidden bg-brand-950">
            {/* Background Image Layer */}
            <div className="absolute inset-0 z-0">
                {hydrated ? (
                    <>
                        <Image 
                            src={backgroundImageUrl}
                            alt={backgroundImageAlt}
                            fill
                            className="object-cover opacity-60 mix-blend-overlay"
                            priority={false}
                        />
                        <div className="absolute inset-0 bg-gradient-to-r from-brand-950 via-brand-950/80 to-transparent" />
                        <div className="absolute inset-0 bg-brand-950/20 backdrop-blur-[2px]" />
                    </>
                ) : (
                    <>
                        <img 
                            src={backgroundImageUrl}
                            alt={backgroundImageAlt}
                            className="w-full h-full object-cover opacity-60 mix-blend-overlay"
                        />
                        <div className="absolute inset-0 bg-gradient-to-r from-brand-950 via-brand-950/60 to-transparent" />
                    </>
                )}
            </div>

            <div className="container mx-auto px-6 max-w-7xl relative z-10">
                <div className="grid grid-cols-1 lg:grid-cols-2 items-center min-h-[400px] gap-12">
                    
                    {/* Left Column: Spacer/Branding (Empty as requested) */}
                    <div className="hidden lg:block h-full" />

                    {/* Right Column: Featured Testimonial Card */}
                    <motion.div
                        initial={{ opacity: 0, x: 40 }}
                        animate={hydrated ? { opacity: 1, x: 0 } : { opacity: 0, x: 40 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.8, ease: "easeOut" }}
                        className="flex justify-center lg:justify-end"
                    >
                        <div className="w-full max-w-lg bg-white/5 backdrop-blur-2xl rounded-2xl border border-white/10 p-10 shadow-2xl relative overflow-hidden group">
                            {/* Decorative Gloss */}
                            <div className="absolute top-0 right-0 w-32 h-32 bg-gold-400/10 rounded-full blur-3xl -mr-16 -mt-16 group-hover:bg-gold-400/20 transition-all duration-500" />
                            
                            <h2 className="text-2xl font-bold text-white font-heading tracking-tight mb-2">
                                Reader Feedback
                            </h2>
                            <p className="text-sm text-slate-400 font-sans mb-8">
                                Perspective from business owners and advisors using Union National Tax resources.
                            </p>

                            <div className="flex gap-1.5 text-gold-400 mb-8">
                                {[...Array(featured.rating)].map((_, i) => (
                                    <Star key={i} className="w-5 h-5 fill-current" />
                                ))}
                            </div>
                            
                            <blockquote className="relative">
                                <p className="text-white font-heading italic text-2xl md:text-3xl font-bold leading-tight mb-12">
                                    &ldquo;{featured.quote}&rdquo;
                                </p>
                            </blockquote>
                            
                            <div className="pt-8 border-t border-white/5 flex items-center gap-5">
                                <div className="h-0.5 w-8 bg-gold-500/50" />
                                <div>
                                    <p className="font-bold text-white text-base tracking-wide uppercase font-body">{featured.clientName}</p>
                                    <p className="text-xs uppercase tracking-[0.2em] text-slate-500 mt-1.5">
                                        {featured.clientTitle} {featured.clientCompany && `• ${featured.clientCompany}`}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                </div>
            </div>
        </section>
    );
}

"use client";

import { motion } from "framer-motion";
import { ArrowRight, BadgeCheck, Lock, ShieldCheck, ShoppingCart, Zap } from "lucide-react";
import { useTranslations } from "next-intl";
import { trackMetaEvent } from "@/components/seo/MetaPixel";
import { useCartStore } from "@/store/useCartStore";
import { useState } from "react";
import { buildCartItemKey } from "@/lib/shop/types";

interface TransactionCardProps {
    id?: string;
    slug: string;
    title: string;
    image: string;
    format: string;
    price: number;
    compareAtPrice?: number;
    buyLink?: string;
    features?: string[];
}

export function TransactionCard({ 
    id, 
    slug, 
    title, 
    image, 
    format, 
    price, 
    compareAtPrice, 
    buyLink, 
    features = [] 
}: TransactionCardProps) {
    const t = useTranslations("Shop.TransactionCard");
    const { addItem, toggleCart } = useCartStore();
    const [isAdded, setIsAdded] = useState(false);
    const primaryFeatures = features.slice(0, 4);

    const formatPrice = (p: number) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 0,
        }).format(p);
    };

    return (
        <motion.aside
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="sticky top-24 h-fit rounded-3xl border border-slate-200 bg-white/90 p-6 shadow-2xl shadow-slate-200/50 backdrop-blur-xl transition-all hover:shadow-gold-500/5"
        >
            <div className="flex items-end justify-between gap-3">
                <div>
                    <div className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{t("strategicAsset")}</div>
                    <div className="mt-2 text-4xl font-bold text-brand-900 font-data tabular-nums tracking-tight">{formatPrice(price)}</div>
                </div>
                {compareAtPrice && (
                    <div className="text-right">
                        <div className="text-sm font-medium text-slate-400 line-through decoration-slate-300 decoration-2">{formatPrice(compareAtPrice)}</div>
                        <div className="mt-1 inline-flex items-center rounded-full bg-emerald-50 border border-emerald-100 px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-widest text-emerald-700">
                             {t("save")} {formatPrice(compareAtPrice - price)}
                        </div>
                    </div>
                )}
            </div>

            <div className="mt-8 grid gap-3">
                <div className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white/50 px-4 py-3 text-[11px] font-bold uppercase tracking-widest text-slate-500 transition-colors hover:border-gold-200 hover:text-brand-900">
                    <Lock className="h-4 w-4 text-gold-500" /> {t("secureCheckout")}
                </div>
                <div className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white/50 px-4 py-3 text-[11px] font-bold uppercase tracking-widest text-slate-500 transition-colors hover:border-gold-200 hover:text-brand-900">
                    <BadgeCheck className="h-4 w-4 text-gold-500" /> {t("lifetimeAccess")}
                </div>
            </div>

            {primaryFeatures.length > 0 && (
                <div className="mt-8">
                    <div className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-4">Included Materials</div>
                    <ul className="space-y-3">
                        {primaryFeatures.filter(Boolean).map((feature, idx) => (
                            <li key={idx} className="flex items-start gap-3 text-sm text-slate-600 font-medium">
                                <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-gold-50 text-gold-600">
                                    <ShieldCheck className="h-3 w-3" />
                                </span>
                                <span className="leading-relaxed">{feature}</span>
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <div className="mt-8 pt-6 border-t border-slate-100 space-y-3">
                <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => {
                        addItem({
                            id: buildCartItemKey(id || slug),
                            productId: id || slug,
                            slug,
                            title,
                            image,
                            format,
                            price,
                            buyLink,
                        });
                        setIsAdded(true);
                        trackMetaEvent("AddToCart", { 
                            content_id: slug, 
                            content_type: "product",
                            value: price,
                            currency: "USD"
                        });
                        // Automatically open cart after short delay
                        setTimeout(() => toggleCart(), 500);
                    }}
                    className="group relative flex w-full items-center justify-center overflow-hidden rounded-xl bg-gradient-to-r from-gold-500 to-gold-400 px-6 py-4 text-sm font-bold uppercase tracking-widest text-brand-900 shadow-xl shadow-gold-500/20 transition-all hover:shadow-gold-500/40"
                >
                    <span className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/40 to-transparent transition-transform duration-1000 group-hover:translate-x-full" />
                    <span className="relative flex items-center gap-2">
                        {isAdded ? "Added to Cart" : t("securePurchase")} <ShoppingCart className="w-3.5 h-3.5 mb-0.5" />
                    </span>
                </motion.button>

                {isAdded && (
                    <motion.button
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        onClick={() => toggleCart()}
                        className="w-full py-3 px-6 rounded-xl border border-slate-200 text-slate-600 font-bold text-xs uppercase tracking-widest hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
                    >
                        View Cart <ArrowRight className="w-3 h-3" />
                    </motion.button>
                )}
                
                <p className="mt-4 text-center text-[10px] font-medium text-slate-400 uppercase tracking-wider">
                    {t("instantDelivery")}
                </p>
            </div>
        </motion.aside>
    );
}

'use client'

import { NextStudio } from 'next-sanity/studio'
